  for(const s of demo.sessions||[])rows.push({id:'credit:'+s.id,title:t('Weekly credit recorded','Недельное начисление записано'),detail:M(s.payout),date:s.date,type:'credit',amount:s.payout,session:s,operationId:s.id});
  for(const r of demo.tickets||[])if(r.reply)rows.push({id:'reply:'+r.id+':'+r.reply,title:t('Your manager replied','Менеджер ответил'),detail:r.subject||r.message,date:r.repliedAt||r.date,type:'reply',ticket:r});
