  if(demo.identityEvent?.updated&&demo.identityEvent.status!=='draft')rows.push({id:'identity:'+demo.identityEvent.updated,title:({submitted:t('Details sent to your manager','Анкета отправлена менеджеру'),reviewed:t('Your manager reviewed your documents','Менеджер просмотрел документы'),changes_requested:t('Your manager requested a clarification','Менеджер запросил уточнение')})[demo.identityEvent.status],detail:t('Documents & details','Документы и данные'),date:demo.identityEvent.updated,type:'identity'});
